<template>
  <div class="min-h-screen p-4">
    <div class="mb-4"><h1 class="text-lg font-bold text-slate-900">Sales Transactions</h1><p class="text-xs text-slate-500">Unified history of in-store, wholesale, and online sales.</p></div>
    <div class="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="s in summary" :key="s.label" class="rounded-xl border bg-white p-4"><p class="text-xs uppercase tracking-wide text-slate-500">{{ s.label }}</p><p class="mt-1 text-xl font-bold" :class="s.color">{{ s.money?money(s.value):s.value }}</p></div></div>
    <Card class="border border-slate-200 shadow-sm"><template #content>
      <div class="mb-4 grid items-end gap-3 md:grid-cols-6"><IconField class="md:col-span-2"><InputIcon class="pi pi-search" /><InputText v-model="filters.search" placeholder="Order number, customer, or contact" size="small" fluid @input="loadLater" /></IconField><Select v-model="filters.channel" :options="channels" optionLabel="label" optionValue="value" placeholder="All channels" showClear size="small" fluid @change="load" /><Select v-model="filters.status" :options="statuses" optionLabel="label" optionValue="value" placeholder="All statuses" showClear size="small" fluid @change="load" /><Select v-model="filters.payment" :options="payments" optionLabel="label" optionValue="value" placeholder="Payment status" showClear size="small" fluid /><Button v-if="hasFilters" label="Clear" severity="secondary" outlined size="small" @click="clear" /></div>
      <DataTable :value="filtered" :loading="loading" dataKey="key" paginator :rows="15" :rowsPerPageOptions="[15,25,50]" rowHover stripedRows class="text-xs" responsiveLayout="scroll">
        <template #empty><div class="py-10 text-center"><i class="pi pi-receipt text-4xl text-slate-300" /><p class="mt-2 text-slate-500">No transactions found.</p></div></template>
        <Column field="order_number" header="Transaction" sortable style="min-width:180px"><template #body="{data}"><button class="font-semibold text-blue-600 hover:underline" @click="view(data)">{{ data.order_number }}</button><p class="mt-1 text-[11px] text-slate-400">{{ dateTime(data.created_at) }}</p></template></Column>
        <Column header="Customer" style="min-width:200px"><template #body="{data}"><p class="font-medium">{{ data.customer_name||'Walk-in' }}</p><p class="text-[11px] text-slate-500">{{ data.customer_contact||'No contact' }}</p></template></Column>
        <Column field="channel" header="Channel" sortable><template #body="{data}"><Tag :value="data.channel" :severity="channelSeverity(data.channel)" /></template></Column>
        <Column header="Branch"><template #body="{data}">{{ data.branch_name||'—' }}</template></Column>
        <Column field="items_count" header="Items" sortable />
        <Column field="total_amount" header="Total" sortable><template #body="{data}"><span class="font-semibold">{{ money(data.total_amount) }}</span></template></Column>
        <Column field="payment_status" header="Payment" sortable><template #body="{data}"><Tag :value="label(data.payment_status||'pending')" :severity="paymentSeverity(data.payment_status)" /></template></Column>
        <Column field="status" header="Order status" sortable><template #body="{data}"><Tag :value="label(data.status)" :severity="statusSeverity(data.status)" /></template></Column>
        <Column header="Actions" frozen alignFrozen="right"><template #body="{data}"><Button label="View" icon="pi pi-eye" outlined rounded size="small" @click="view(data)" /></template></Column>
      </DataTable>
    </template></Card>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { router } from '@inertiajs/vue3'; import { useToast } from 'primevue/usetoast'; import salesService from '@/services/sales.service'; import Button from 'primevue/button'; import Card from 'primevue/card'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import IconField from 'primevue/iconfield'; import InputIcon from 'primevue/inputicon'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Tag from 'primevue/tag'
const toast=useToast(),loading=ref(false),rows=ref<any[]>([]),filters=reactive({search:'',channel:null as string|null,status:null as string|null,payment:null as string|null});let timer:any
const channels=[{label:'In-Store',value:'pos'},{label:'Wholesale',value:'wholesale'},{label:'Online',value:'ecommerce'}],statuses=[{label:'Pending',value:'pending'},{label:'Processing',value:'processing'},{label:'Completed',value:'completed'},{label:'Cancelled',value:'cancelled'}],payments=[{label:'Paid',value:'paid'},{label:'Pending',value:'pending'},{label:'Failed',value:'failed'},{label:'Refunded',value:'refunded'}]
const filtered=computed(()=>filters.payment?rows.value.filter(x=>String(x.payment_status).toLowerCase()===filters.payment):rows.value),hasFilters=computed(()=>!!(filters.search||filters.channel||filters.status||filters.payment));const summary=computed(()=>{const paid=rows.value.filter(x=>String(x.payment_status).toLowerCase()==='paid');return[{label:'Transactions',value:rows.value.length,color:'text-slate-900'},{label:'Paid revenue',value:paid.reduce((s,x)=>s+(+x.total_amount||0),0),money:true,color:'text-emerald-600'},{label:'Pending payment',value:rows.value.filter(x=>String(x.payment_status).toLowerCase()==='pending').length,color:'text-amber-600'},{label:'Online orders',value:rows.value.filter(x=>x.order_type==='ecommerce').length,color:'text-blue-600'}]})
const load=async()=>{loading.value=true;try{const r=await salesService.getUnifiedOrders({search:filters.search,channel:filters.channel,status:filters.status});rows.value=r.data||[]}catch(e:any){toast.add({severity:'error',summary:'Unable to load transactions',detail:e.response?.data?.message||'Please try again.',life:3000})}finally{loading.value=false}};const loadLater=()=>{clearTimeout(timer);timer=setTimeout(load,300)},clear=()=>{Object.assign(filters,{search:'',channel:null,status:null,payment:null});load()},view=(x:any)=>router.visit(`/sales/transactions/${x.order_type}/${x.id}`)
const money=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(+v||0),label=(v:any)=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),dateTime=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';const channelSeverity=(v:string)=>v==='Online'?'info':v==='Wholesale'?'warn':'secondary',paymentSeverity=(v:string)=>v==='paid'?'success':v==='failed'?'danger':v==='refunded'?'info':'warn',statusSeverity=(v:string)=>['completed','delivered'].includes(String(v).toLowerCase())?'success':['cancelled','declined'].includes(String(v).toLowerCase())?'danger':'info';onMounted(load)
</script>
